import numpy as np, pandas as pd
from scipy.optimize import least_squares
m=pd.read_csv('/task/work/well_measurements.tsv',sep='\t')
u=m[m.qc_pass==1]
vehicle=u[u.role=='vehicle']
base={'marker_per_cell':float(vehicle.marker_per_cell.mean()),'n_cells':float(vehicle.n_cells.mean())}
print('vehicle baseline',base)

def model(c,bottom,ec50,h):
    return bottom+(1-bottom)/(1+(c/ec50)**h)

def crossing(bottom,ec50,h,maxc):
    # y=0.5 => (c/ec50)^h = 0.5/(0.5-bottom)
    if bottom>=0.5:
        return None
    return ec50*(0.5/(0.5-bottom))**(1/h)

for cp,g in u[u.role=='compound'].groupby('compound',sort=True):
    print('\n###',cp)
    for readout in ['marker_per_cell','n_cells']:
        gg=g.sort_values('dose_uM')
        c=gg.dose_uM.to_numpy(float)
        y=gg[readout].to_numpy(float)/base[readout]
        maxc=float(c.max())
        best=None
        for b0 in [0,.1,.2,.3,.4]:
          for e0 in [0.01,.03,.1,.3,1,3,10,30]:
           for h0 in [.5,1,2,4,8]:
            try:
             z=least_squares(lambda p:model(c,p[0],np.exp(p[1]),np.exp(p[2]))-y,
                             [b0,np.log(e0),np.log(h0)],bounds=([-1e-8,-15,-5],[.999999,5,5]),max_nfev=5000)
             ss=float(np.sum(z.fun**2))
             if best is None or ss<best[0]: best=(ss,z)
            except Exception: pass
        ss,z=best
        b,ec,h=float(z.x[0]),float(np.exp(z.x[1])),float(np.exp(z.x[2]))
        cross=crossing(b,ec,h,maxc)
        pred=model(c,b,ec,h)
        potency='inactive' if cross is None or cross>maxc else cross
        print(f'{readout:16} bottom={b:.4f} ec50={ec:.5g} h={h:.4g} sse={ss:.4g} cross={None if cross is None else round(cross,5)} potency={potency if isinstance(potency,str) else round(potency,5)}')
        print(' observed',np.round(y,3).tolist())
        print(' predicted',np.round(pred,3).tolist())
